const wording = [
  ['唔宜','唔應該'], ['不宜','唔應該'], ['近文','前後嗰段經文'],
  ['語義範圍','個字可以有嘅意思'], ['離體靈魂','離開身體嘅靈魂'],
  ['此處','呢度'], ['殷勤講論','經常講'], ['訓誨','教導']
];
const plain = text => wording.reduce((s,[from,to]) => s.replaceAll(from,to),text);
export function reviseCopy(question) {
  const edit = COPY_EDITS[question.id] || {};
  const options = edit.options || question.options.map((option,index) => index === 0 ? edit.option0 || option : option);
  return { ...question, question:plain(edit.question || question.question), options:options.map(plain), explanation:plain(edit.explanation || question.explanation) };
}
